--
-- Structure de la vue `vieu_taux_pluri`
--
DROP TABLE IF EXISTS `vieu_taux_pluri`;

DROP VIEW IF EXISTS `vieu_taux_pluri`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vieu_taux_pluri`  AS  select if(`view_cible_pluri`.`cible` > 0 and `view_suivi_pluri`.`suivi` > 0,`view_suivi_pluri`.`suivi` / `view_cible_pluri`.`cible`,0) AS `taux`,`view_cible_pluri`.`code` AS `code`,`view_cible_pluri`.`projet` AS `projet` from (`view_cible_pluri` left join `view_suivi_pluri` on(`view_cible_pluri`.`id_plan` = `view_suivi_pluri`.`indicateur_cr`)) group by `view_cible_pluri`.`code`,`view_cible_pluri`.`projet` order by if(`view_cible_pluri`.`cible` > 0 and `view_suivi_pluri`.`suivi` > 0,`view_suivi_pluri`.`suivi` / `view_cible_pluri`.`cible`,0) ;

