--
-- Structure de la vue `view_cible_pluri`
--
DROP TABLE IF EXISTS `view_cible_pluri`;

DROP VIEW IF EXISTS `view_cible_pluri`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_cible_pluri`  AS  select `activite_projet`.`code` AS `code`,`plan_pluri_indicateur`.`id_plan` AS `id_plan`,`plan_pluri_indicateur`.`projet` AS `projet`,sum(`cible_indicateur_pa`.`valeur_cible`) AS `cible` from ((`activite_projet` join `plan_pluri_indicateur`) join `cible_indicateur_pa`) where `activite_projet`.`code` = convert(`plan_pluri_indicateur`.`activite_pa` using utf8) and `cible_indicateur_pa`.`indicateur_ppa` = `plan_pluri_indicateur`.`id_plan` and `plan_pluri_indicateur`.`type_ind` = 1 group by `activite_projet`.`code`,`plan_pluri_indicateur`.`id_plan`,`plan_pluri_indicateur`.`projet` ;

-- --------------------------------------------------------

--
-- Structure de la vue `view_suivi_pluri`
--
DROP TABLE IF EXISTS `view_suivi_pluri`;

DROP VIEW IF EXISTS `view_suivi_pluri`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_suivi_pluri`  AS  select `ptba`.`code_activite_ptba` AS `code_activite_ptba`,`indicateur_tache`.`indicateur_cr` AS `indicateur_cr`,`ptba`.`projet` AS `projet`,sum(`suivi_indicateur_tache`.`valeur_suivi`) AS `suivi` from ((`ptba` join `indicateur_tache`) join `suivi_indicateur_tache`) where `ptba`.`id_ptba` = `indicateur_tache`.`id_activite` and `indicateur_tache`.`id_indicateur_tache` = `suivi_indicateur_tache`.`indicateur` and `ptba`.`annee` in (select `Max_version_Ptba`.`id_version` from `Max_version_Ptba`) group by `ptba`.`code_activite_ptba`,`indicateur_tache`.`indicateur_cr`,`ptba`.`projet` ;

-- --------------------------------------------------------

--
-- Structure de la vue `v_suivi_activite_ptba`
--
DROP TABLE IF EXISTS `v_suivi_activite_ptba`;

DROP VIEW IF EXISTS `v_suivi_activite_ptba`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_suivi_activite_ptba`  AS  select round(sum(if(`groupe_tache`.`valider` = 1 and `groupe_tache`.`n_lot` > 0,`groupe_tache`.`proportion` * `groupe_tache`.`jalon` / `groupe_tache`.`n_lot`,0)),0) AS `proportions`,`ptba`.`id_ptba` AS `id_ptba`,`ptba`.`annee` AS `annee`,`ptba`.`projet` AS `projet`,`ptba`.`code_activite_ptba` AS `code_activite_ptba` from (`ptba` join `groupe_tache`) where `ptba`.`id_ptba` = `groupe_tache`.`id_activite` group by `ptba`.`id_ptba`,`ptba`.`code_activite_ptba`,`ptba`.`annee`,`ptba`.`projet` ;
